package com.cineflow.bug.controller;
import com.cineflow.bug.dto.LookupResponse; import com.cineflow.bug.entity.LookupEntity; import com.cineflow.bug.exception.BusinessValidationException; import com.cineflow.bug.repository.*; import com.cineflow.bug.service.BugService; import java.util.*; import lombok.RequiredArgsConstructor; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/metadata") @RequiredArgsConstructor public class MetadataController {
  private final DepartmentRepository departments; private final PriorityRepository priorities; private final SeverityRepository severities; private final BugStatusRepository statuses; private final AttachmentTypeRepository attachmentTypes; private final FrameTypeRepository frameTypes; private final AnnotationTypeRepository annotationTypes;
  @GetMapping("/{type}") public List<LookupResponse> list(@PathVariable String type){JpaRepository<? extends LookupEntity,Long> repo=switch(type){case "departments"->departments;case "priorities"->priorities;case "severities"->severities;case "statuses"->statuses;case "attachment-types"->attachmentTypes;case "frame-types"->frameTypes;case "annotation-types"->annotationTypes;default->throw new BusinessValidationException("Unknown metadata type: "+type);};return repo.findAll().stream().filter(LookupEntity::isActive).map(BugService::lookup).toList();}
}
